corporate_design.toad_component_blueprint:
canvas {
  size: 880px 580px;
  fill: #0D0D0D;
  font-family: "Cormorant Garamond, serif";
}

>gold = #D4AF37;
>white = #FAF8F5;

rect #scoreCard {
  at: center of canvas;
  size: 780px 480px;
  fill: #141414;
  stroke: >gold;
  stroke-width: 1px;
}

text #orchHeader {
  at: top center of #scoreCard offset 0px 40px;
  content: "SYMPHONIA // MEISTERKONZERTE 2026";
  font-size: 14px;
  font-weight: 600;
  color: >gold;
}

text #symphonyTitle {
  at: below #orchHeader offset 16px;
  content: "MAHLER: SINFONIE NR. 5 IN CIS-MOLL";
  font-size: 30px;
  font-weight: 700;
  color: >white;
}
